using System; using System.IO; using UnityEngine; namespace HonourWar { public sealed class HonourWarScreenshotDirector:MonoBehaviour { public string LastPath=""; public void Capture(){var dir=Path.Combine(Application.persistentDataPath,"HonourWarScreenshots");Directory.CreateDirectory(dir);LastPath=Path.Combine(dir,"HonourWar-REAL-GAMEPLAY-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".png");ScreenCapture.CaptureScreenshot(LastPath,2);Debug.Log("HONOUR_WAR_REAL_GAMEPLAY_SCREENSHOT="+LastPath);} } }